import '../features/home/home_screen.dart';import '../features/search/search_screen.dart';import '../features/selling/sell_screen.dart';import '../features/messages/messages_screen.dart';import '../features/profile/profile_screen.dart';
class MercDealApp extends StatelessWidget{const MercDealApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'MercDeal',theme:MercDealTheme.dark(),home:const MercDealSplash());}
class MainShell extends StatefulWidget{const MainShell({super.key});@override State<MainShell> createState()=>_MainShellState();}
class _MainShellState extends State<MainShell>{int index=0;final pages=const[HomeScreen(),SearchScreen(),SellScreen(),MessagesScreen(),ProfileScreen()];@override Widget build(BuildContext c)=>Scaffold(body:IndexedStack(index:index,children:pages),bottomNavigationBar:NavigationBar(selectedIndex:index,onDestinationSelected:(v)=>setState(()=>index=v),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),selectedIcon:Icon(Icons.home_rounded),label:'Home'),NavigationDestination(icon:Icon(Icons.search_rounded),label:'Cerca'),NavigationDestination(icon:Icon(Icons.add_circle_outline_rounded),selectedIcon:Icon(Icons.add_circle_rounded),label:'Vendi'),NavigationDestination(icon:Icon(Icons.forum_outlined),selectedIcon:Icon(Icons.forum_rounded),label:'Messaggi'),NavigationDestination(icon:Icon(Icons.person_outline_rounded),selectedIcon:Icon(Icons.person_rounded),label:'Profilo')]));}
