class _MercDealSplashState extends State<MercDealSplash>{@override void initState(){super.initState();Timer(const Duration(milliseconds:900),(){if(mounted)Navigator.of(context).pushReplacement(MaterialPageRoute(builder:(_)=>const MainShell()));});}@override Widget build(BuildContext c)=>Scaffold(body:Container(decoration:const BoxDecoration(gradient:LinearGradient(begin:Alignment.topLeft,end:Alignment.bottomRight,colors:[Color(0xFF06130F),MercDealTheme.navy,Color(0xFF06101D)])),child:Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Container(width:96,height:96,decoration:BoxDecoration(borderRadius:BorderRadius.circular(30),gradient:const LinearGradient(colors:[MercDealTheme.green,MercDealTheme.blue]),boxShadow:[BoxShadow(color:MercDealTheme.green,blurRadius:38,spreadRadius:-15)]),child:const Icon(Icons.shopping_cart_rounded,size:48,color:Color(0xFF03100A))),const SizedBox(height:20),const Text('MercDeal',style:TextStyle(fontSize:36,fontWeight:FontWeight.w900,letterSpacing:-1)),const SizedBox(height:5),const Text('Il prezzo scende. L’affare sale.',style:TextStyle(color:Color(0x99FFFFFF),fontWeight:FontWeight.w600))]))));}
